INSERT INTO `failed_jobs` VALUES (1,'database','queue','{\"uuid\":\"f2ebd8df-9573-4831-8704-f0af89da2bd9\",\"displayName\":\"APP\\\\jobs\\\\notifications\\\\IssuePublishedNotifyUsers\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":3,\"failOnTimeout\":true,\"backoff\":\"5\",\"timeout\":60,\"retryUntil\":null,\"data\":{\"commandName\":\"APP\\\\jobs\\\\notifications\\\\IssuePublishedNotifyUsers\",\"command\":\"O:48:\\\"APP\\\\jobs\\\\notifications\\\\IssuePublishedNotifyUsers\\\":8:{s:15:\\\"\\u0000*\\u0000recipientIds\\\";O:29:\\\"Illuminate\\\\Support\\\\Collection\\\":2:{s:8:\\\"\\u0000*\\u0000items\\\";a:1:{i:0;i:1;}s:28:\\\"\\u0000*\\u0000escapeWhenCastingToString\\\";b:0;}s:12:\\\"\\u0000*\\u0000contextId\\\";i:1;s:8:\\\"\\u0000*\\u0000issue\\\";O:15:\\\"APP\\\\issue\\\\Issue\\\":6:{s:5:\\\"_data\\\";a:21:{s:2:\\\"id\\\";i:4;s:9:\\\"journalId\\\";i:1;s:6:\\\"volume\\\";i:5;s:6:\\\"number\\\";s:1:\\\"1\\\";s:4:\\\"year\\\";i:2024;s:9:\\\"published\\\";i:1;s:13:\\\"datePublished\\\";s:19:\\\"2025-07-18 09:14:48\\\";s:12:\\\"dateNotified\\\";N;s:12:\\\"lastModified\\\";s:19:\\\"2025-06-10 12:25:39\\\";s:12:\\\"accessStatus\\\";i:1;s:14:\\\"openAccessDate\\\";N;s:10:\\\"showVolume\\\";b:1;s:10:\\\"showNumber\\\";b:1;s:8:\\\"showYear\\\";b:1;s:9:\\\"showTitle\\\";b:1;s:13:\\\"styleFileName\\\";N;s:21:\\\"originalStyleFileName\\\";N;s:7:\\\"urlPath\\\";N;s:5:\\\"doiId\\\";N;s:11:\\\"description\\\";a:1:{s:2:\\\"en\\\";s:1096:\\\"<p>The <strong>Ilorin Journal of Business Education (IJBE)<\\/strong> is a quarterly, blind peer-reviewed, research-based journal that provides a reputable platform for disseminating contemporary research, theoretical development, and critical discourse in the broad areas of Education, Business, Administration, and Entrepreneurship. The journal is published by the Department of Educational Management, Faculty of Education, University of Ilorin, Nigeria.&nbsp;<\\/p>\\r\\n<p data-start=\\\"796\\\" data-end=\\\"1131\\\">IJBE is committed to promoting scholarship that bridges theory and practice, with an emphasis on how education intersects with business and administrative functions in both public and private sectors. The journal seeks to encourage innovative thinking, policy development, and the improvement of professional practice in areas such as: Business education pedagogy and curriculum development, educational management and leadership, Entrepreneurial education and skill development, Organizational behaviors and institutional performance, Policy analysis in educational and business contexts.<\\/p>\\\";}s:5:\\\"title\\\";a:1:{s:2:\\\"en\\\";s:43:\\\"Ilorin Journal of Business Education (IJBE)\\\";}}s:20:\\\"_hasLoadableAdapters\\\";b:0;s:27:\\\"_metadataExtractionAdapters\\\";a:0:{}s:25:\\\"_extractionAdaptersLoaded\\\";b:0;s:26:\\\"_metadataInjectionAdapters\\\";a:0:{}s:24:\\\"_injectionAdaptersLoaded\\\";b:0;}s:9:\\\"\\u0000*\\u0000locale\\\";s:2:\\\"en\\\";s:9:\\\"\\u0000*\\u0000sender\\\";O:13:\\\"PKP\\\\user\\\\User\\\":7:{s:5:\\\"_data\\\";a:27:{s:2:\\\"id\\\";i:2;s:8:\\\"userName\\\";s:9:\\\"oluwalola\\\";s:8:\\\"password\\\";s:60:\\\"$2y$10$XUDJrF5A2DkKlNK.5EbWf.1rEThXmqNmULyO38EfznGlPTcl1Yyy.\\\";s:5:\\\"email\\\";s:28:\\\"oluwalola.fk@unilorin.edu.ng\\\";s:3:\\\"url\\\";s:0:\\\"\\\";s:5:\\\"phone\\\";s:0:\\\"\\\";s:14:\\\"mailingAddress\\\";s:0:\\\"\\\";s:14:\\\"billingAddress\\\";N;s:7:\\\"country\\\";s:2:\\\"NG\\\";s:7:\\\"locales\\\";a:0:{}s:6:\\\"gossip\\\";N;s:13:\\\"dateLastEmail\\\";N;s:14:\\\"dateRegistered\\\";s:19:\\\"2025-05-09 22:37:42\\\";s:13:\\\"dateValidated\\\";N;s:13:\\\"dateLastLogin\\\";s:19:\\\"2025-07-18 08:51:38\\\";s:18:\\\"mustChangePassword\\\";b:0;s:7:\\\"authStr\\\";N;s:8:\\\"disabled\\\";b:0;s:14:\\\"disabledReason\\\";N;s:10:\\\"inlineHelp\\\";b:1;s:5:\\\"orcid\\\";s:0:\\\"\\\";s:11:\\\"affiliation\\\";a:1:{s:2:\\\"en\\\";s:38:\\\"University of Ilorin, Ilorin, Nigeria.\\\";}s:9:\\\"biography\\\";a:1:{s:2:\\\"en\\\";s:0